-- ══════════════════════════════════════════════════════════
--  Módulo 01: las actividades se hacen en el campus
--
--  Las lecciones del módulo 01 decían «descarga la plantilla y entrégala en
--  Classroom». Ahora cada actividad es un formulario del campus (0036), así
--  que el texto cambia: se quitan las plantillas XLSX y los enunciados que
--  mandaban a Classroom, las casillas «comprueba que» (el estado real lo
--  dan las actividades) y las frases sobre Classroom. Las lecturas siguen.
--
--  Cada UPDATE sólo se aplica si la lección está exactamente como estaba
--  (md5 del contenido): si alguien la ha editado, falla y no toca nada.
-- ══════════════════════════════════════════════════════════

do $$
declare n integer;
begin
  update public.lessons set content_blocks = $j$[{"t": "h", "text": "Por qué hay material previo", "level": 2}, {"t": "p", "text": "Las cuatro horas en directo no se usan para explicarte teoría, sino para trabajar contigo. La teoría la ves aquí, cuando te venga bien. Así llegas a clase sabiendo de qué hablamos y el tiempo en directo se dedica a lo que no se puede hacer solo."}, {"t": "note", "kind": "idea", "text": "Haz la ficha de presentación, el Test de Punto de Partida y el estudio sobre la penalización del remoto. Con eso puedes seguir la sesión.", "title": "Si solo tienes una hora"}, {"t": "table", "head": ["Material", "Formato", "Tiempo", "Obligatorio"], "rows": [["Ficha de presentación", "Formulario", "10 min", "Sí"], ["Mitos y verdades, con Nick Bloom", "Pódcast", "30 min", "Recomendado"], ["Los diez modelos de trabajo remoto", "Lectura", "15 min", "Recomendado"], ["La penalización de trabajar en remoto", "Estudio", "20 min", "Sí"], ["La otra mitad de la historia (Nature)", "Lectura", "15 min", "Opcional"], ["State of Global Hiring", "Informe", "15 min", "Recomendado"], ["Test de Punto de Partida", "Formulario", "20 min", "Sí"], ["Async Autonomy Baseline", "Cuestionario", "15 min", "Recomendado"], ["Encuesta de expectativas", "Encuesta anónima", "3 min", "Sí"], ["La trampa de la proximidad", "Micro-juego", "10 min", "Opcional"]], "caption": "Todo el material previo del módulo, con su tiempo orientativo."}, {"t": "h", "text": "La ficha de presentación", "level": 3}, {"t": "p", "text": "En la hora 1 cada persona se presenta en 60 segundos. El docente lee tu ficha antes de la sesión para llamarte por tu nombre y conectar los ejemplos con tu caso. La rellenas aquí, más abajo, en «Actividades de esta lección»."}, {"t": "checklist", "items": ["Nombre y cómo prefieres que te llamen", "De dónde eres y dónde estás ahora", "A qué te dedicas, en una frase que entienda alguien de otro sector", "Por qué haces este curso", "Tu objetivo a 12 meses, con una cifra o una fecha si puedes", "Tu huso horario y con quién necesitas solapar horas"], "title": "Lo que te pide la ficha"}, {"t": "note", "kind": "aviso", "text": "La ficha la ven el profesorado y tu cohorte. No incluyas números de documento, direcciones, teléfonos personales ni datos salariales concretos.", "title": "Privacidad"}, {"t": "h", "text": "Los cuestionarios del campus", "level": 3}, {"t": "p", "text": "El Test de Punto de Partida (26 preguntas) mide tus condiciones de vida para el trabajo remoto y te sitúa en uno de cinco estadios. El Async Autonomy Baseline (12 preguntas) mide tus hábitos de comunicación y tu autonomía. Ninguno puntúa para nota. Responde por la vida que tienes, no por la que quieres: quien se infla las respuestas se queda sin diagnóstico. Se hacen aquí mismo, más abajo, en «Actividades de esta lección»."}, {"t": "resources", "items": [{"url": "https://siepr.stanford.edu/av/Econ-To-Go-podcast-how-remote-work-redefining-our-lives", "note": "En inglés, 30 min", "label": "Pódcast Econ To Go: cómo el trabajo remoto está redefiniendo nuestras vidas (Nick Bloom, SIEPR Stanford)"}, {"url": "https://handbook.gitlab.com/handbook/company/culture/all-remote/stages/", "note": "Documento vivo, en inglés", "label": "GitLab Handbook: los modelos de trabajo remoto e híbrido"}, {"url": "https://doi.org/10.1371/journal.pone.0303307", "note": "Obligatorio. Si solo lees una parte, el apartado Results", "label": "Kasperska, Matysiak y Cukrowska-Torzewska: la penalización del remoto (PLOS ONE, 2024)"}, {"url": "https://doi.org/10.1177/09500170251325769", "label": "Segundo estudio de los mismos autores sobre los mecanismos (Work, Employment and Society, 2025)"}, {"url": "https://www.nature.com/articles/s41586-024-07500-2", "note": "Opcional. El resumen y los resultados", "label": "Bloom, Han y Liang: ensayo controlado sobre trabajo híbrido (Nature, 2024)"}, {"url": "https://www.deel.com/global-hiring-report-2026/", "note": "Ve a las tablas de tu función y tu región. Es un informe de parte: contrasta las cifras", "label": "Deel: State of Global Hiring 2026"}], "title": "Fuentes de interés"}, {"t": "resources", "items": [{"url": "https://jzmllhwkplpfmjddqknh.supabase.co/storage/v1/object/public/lesson-assets/curso/m01/preclase/01.-M1-Material-previo-ES.docx", "note": "La guía completa de lo que haces antes de clase", "label": "Material previo del módulo 01"}], "title": "Descargas"}]$j$::jsonb
  where id = 'c968776d-9817-4388-adbe-db578bee54d3' and md5(content_blocks::text) = '5182cb9245ba3624c993c6b24a03c7f4';
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'La lección 1 (es) ha cambiado: revisa antes de aplicar'; end if;

  update public.lessons set content_blocks_en = $j$[{"t": "h", "text": "Why there is pre-class material", "level": 2}, {"t": "p", "text": "The four live hours are for working with you, not for explaining theory at you. The theory lives here, so you can go through it whenever suits you. You arrive knowing what we will talk about, and class time goes to the things you cannot do on your own."}, {"t": "note", "kind": "idea", "text": "Do the intro card, the Starting Point Test and the study on the remote work penalty. That is enough to follow the session.", "title": "If you only have an hour"}, {"t": "table", "head": ["Material", "Format", "Time", "Required"], "rows": [["Intro card", "Form", "10 min", "Yes"], ["Myths and truths, with Nick Bloom", "Podcast", "30 min", "Recommended"], ["The ten models of remote work", "Reading", "15 min", "Recommended"], ["The remote work penalty", "Study", "20 min", "Yes"], ["The other half of the story (Nature)", "Reading", "15 min", "Optional"], ["State of Global Hiring", "Report", "15 min", "Recommended"], ["Starting Point Test", "Form", "20 min", "Yes"], ["Async Autonomy Baseline", "Questionnaire", "15 min", "Recommended"], ["Expectations poll", "Anonymous poll", "3 min", "Yes"], ["The Proximity Trap", "Micro-game", "10 min", "Optional"]], "caption": "All the module's pre-class material, with approximate timings."}, {"t": "h", "text": "The intro card", "level": 3}, {"t": "p", "text": "In hour 1 everyone introduces themselves in 60 seconds. The teacher reads your card beforehand so they can call you by name and link the examples to your situation. You fill it in here, further down, under “Activities in this lesson”."}, {"t": "checklist", "items": ["Your name and what you like to be called", "Where you are from and where you are now", "What you do, in one sentenced someone from another sector would understand", "Why you are taking this course", "Your 12-month goal, with a figure or a date if you can", "Your time zone and who you need overlapping hours with"], "title": "What the card asks for"}, {"t": "note", "kind": "aviso", "text": "Teachers and your cohort can see the card. Leave out ID numbers, addresses, personal phone numbers and specific salary details.", "title": "Privacy"}, {"t": "h", "text": "The campus questionnaires", "level": 3}, {"t": "p", "text": "The Starting Point Test (26 questions) looks at your life conditions for remote work and places you in one of five stages. The Async Autonomy Baseline (12 questions) looks at how you communicate and how well you work unsupervised. Neither counts towards your grade. Answer for the life you have, not the one you want: inflated answers leave you without a diagnosis. You do them right here, further down, under “Activities in this lesson”."}, {"t": "resources", "items": [{"url": "https://siepr.stanford.edu/av/Econ-To-Go-podcast-how-remote-work-redefining-our-lives", "note": "30 min", "label": "Econ To Go podcast: how remote work is redefining our lives (Nick Bloom, SIEPR Stanford)"}, {"url": "https://handbook.gitlab.com/handbook/company/culture/all-remote/stages/", "note": "A living document", "label": "GitLab Handbook: the stages of remote and hybrid work"}, {"url": "https://doi.org/10.1371/journal.pone.0303307", "note": "Required. If you only read one part, read Results", "label": "Kasperska, Matysiak and Cukrowska-Torzewska: the remote work penalty (PLOS ONE, 2024)"}, {"url": "https://doi.org/10.1177/09500170251325769", "label": "The same authors on the mechanisms behind the effect (Work, Employment and Society, 2025)"}, {"url": "https://www.nature.com/articles/s41586-024-07500-2", "note": "Optional. The abstract and the results", "label": "Bloom, Han and Liang: randomised trial on hybrid work (Nature, 2024)"}, {"url": "https://www.deel.com/global-hiring-report-2026/", "note": "Go straight to the tables for your role and region. It is a vendor report: cross-check the figures", "label": "Deel: State of Global Hiring 2026"}], "title": "Further sources"}, {"t": "resources", "items": [{"url": "https://jzmllhwkplpfmjddqknh.supabase.co/storage/v1/object/public/lesson-assets/curso/m01/preclase/01.-M1-Pre-class-material-EN.docx", "note": "The full guide to what you do before class", "label": "Module 01 pre-class material"}], "title": "Downloads"}]$j$::jsonb
  where id = 'c968776d-9817-4388-adbe-db578bee54d3' and md5(content_blocks_en::text) = 'b4b66bef6676014a4f3dbef36bf20c0d';
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'La lección 1 (en) ha cambiado: revisa antes de aplicar'; end if;

  update public.lessons set content_blocks = $j$[{"t": "p", "text": "La primera hora convierte la sala en una cohorte y cambia el punto de partida: dejas de verte como un empleado visible en un sitio y empiezas a pensar como un proveedor de resultados de una sola persona. Sales con tu puntuación en los cinco ejes y tu fila de la Matriz Proveedor de Valor."}, {"t": "ul", "items": ["Presentaciones de 60 segundos y el retrato de la cohorte", "Del sitio donde trabajas al resultado que entregas", "El sesgo de proximidad y cómo contrarrestarlo", "La Matriz de Competencias Remotas y el mapa del curso"]}, {"t": "checklist", "items": ["Tu ficha de presentación enviada, y tu versión corta para los 60 segundos", "El resultado de tu Test de Punto de Partida", "La Tarea 01 abierta en el campus (más abajo, en «Actividades de esta lección»)"], "title": "Trae preparado"}, {"t": "note", "kind": "idea", "text": "Fallar no cuesta nada. Si quieres prepararte, la lectura de apoyo trae las ocho creencias con su fuente: tápate la respuesta, decide si te la crees y solo entonces mírala.", "title": "Durante la hora hay trivia de mitos"}, {"t": "h", "text": "Tarea 01 · Diagnóstico de Preparación Remota", "level": 3}, {"t": "steps", "items": [{"text": "Da una nota de 1 a 5 a cada uno de los cinco ejes de la Matriz de Competencias, con una línea de justificación.", "title": "Puntúate"}, {"text": "Una frase verificable: un verbo, a quién, qué cambia y el número que lo demuestra.", "title": "Escribe tu frase de valor"}, {"text": "Nombra el eje en el que vas a trabajar durante el curso.", "title": "Elige tu eje de foco"}]}, {"t": "p", "text": "Se hace y se entrega aquí, en el campus: está más abajo, en «Actividades de esta lección». Plazo: el viernes de la semana de la clase, a las 23:59 (hora de Madrid)."}, {"t": "note", "kind": "aviso", "text": "Esta puntuación se repite en el módulo 14. La diferencia entre las dos fotos es la medida más honesta de lo que has cambiado.", "title": "No te infles"}, {"t": "resources", "items": [{"url": "https://jzmllhwkplpfmjddqknh.supabase.co/storage/v1/object/public/lesson-assets/curso/m01/hora-1/06.-M1-Mitos-lectura-apoyo-ES.pdf", "note": "Lectura de apoyo, 15 min", "label": "Mitos y realidad: ocho creencias sobre el trabajo remoto, con su fuente"}], "title": "Descargas"}]$j$::jsonb
  where id = 'bf3d6aca-2c5a-453f-b949-5d8d8798ccdb' and md5(content_blocks::text) = '16e471d7ad4930d8d8d532c304e92046';
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'La lección 2 (es) ha cambiado: revisa antes de aplicar'; end if;

  update public.lessons set content_blocks_en = $j$[{"t": "p", "text": "The first hour turns the room into a cohort and shifts your starting point: you stop seeing yourself as an employee who is visible in a place and start thinking like a one-person provider of results. You leave with your score on the five axes and your row of the Value Provider Matrix."}, {"t": "ul", "items": ["60-second introductions and a portrait of the cohort", "From where you work to what you deliver", "Proximity bias and how to counter it", "The Remote Competency Matrix and the course map"]}, {"t": "checklist", "items": ["Your intro card submitted, plus your short version for the 60 seconds", "Your Starting Point Test result", "Assignment 01 open on the campus (further down, under “Activities in this lesson”)"], "title": "Come prepared with"}, {"t": "note", "kind": "idea", "text": "Getting it wrong costs nothing. If you want to prepare, the support reading covers the eight beliefs with their sources: cover the answer, decide whether you believe it, then look.", "title": "There is a myths quiz during the hour"}, {"t": "h", "text": "Assignment 01 · Remote Readiness Diagnostic", "level": 3}, {"t": "steps", "items": [{"text": "Give each of the five Competency Matrix axes a score from 1 to 5, with one line of justification.", "title": "Score yourself"}, {"text": "One verifiable sentence: a verb, who for, what changes and the number that proves it.", "title": "Write your value statement"}, {"text": "Name the axis you will work on during the course.", "title": "Pick your focus axis"}]}, {"t": "p", "text": "You do it and submit it here, on the campus: it's further down, under “Activities in this lesson”. Deadline: the Friday of class week, at 23:59 (Madrid time)."}, {"t": "note", "kind": "aviso", "text": "You repeat this scoring in module 14. The gap between the two snapshots is the most honest measure of how much you have changed.", "title": "Do not inflate it"}, {"t": "resources", "items": [{"url": "https://jzmllhwkplpfmjddqknh.supabase.co/storage/v1/object/public/lesson-assets/curso/m01/hora-1/06.-M1-Myths-reading-EN.pdf", "note": "Support reading, 15 min", "label": "Myths and reality: eight beliefs about remote work, with sources"}], "title": "Downloads"}]$j$::jsonb
  where id = 'bf3d6aca-2c5a-453f-b949-5d8d8798ccdb' and md5(content_blocks_en::text) = '02f35912ecdd19581352111330c7e2f4';
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'La lección 2 (en) ha cambiado: revisa antes de aplicar'; end if;

  update public.lessons set content_blocks = $j$[{"t": "p", "text": "En remoto te ascienden menos porque quien decide no tiene información sobre tu desempeño. Esta hora monta la respuesta: el Motor de Visibilidad, un sistema personal que convierte tu trabajo en evidencia comprobable. Sales con el sistema funcionando y tres métricas de resultado escritas."}, {"t": "ul", "items": ["Qué es el Motor de Visibilidad y sus cinco componentes: RECAP", "Un recap semanal real, abierto en pantalla", "Cómo distinguir una métrica de resultado de una de actividad"]}, {"t": "checklist", "items": ["Tu fila de la Matriz Proveedor de Valor de la hora 1", "Una idea de qué herramienta usas a diario: un documento, un canal o un tablero", "La Tarea 02 abierta en el campus (más abajo, en «Actividades de esta lección»)"], "title": "Trae preparado"}, {"t": "h", "text": "Tarea 02 · Monta tu Motor de Visibilidad", "level": 3}, {"t": "steps", "items": [{"text": "En la herramienta que ya usas, con los cinco campos RECAP: Registro, Evidencia, Consecuencia, Audiencia y Publicación.", "title": "Monta el motor"}, {"text": "En la plantilla de métricas. Cada una tiene que pasar los cuatro filtros que verás en clase.", "title": "Escribe tres métricas de resultado"}, {"text": "Al canal que quien decide lee de verdad, no a una carpeta privada.", "title": "Envía tu primer recap"}]}, {"t": "p", "text": "Lo entregas aquí, en el campus, más abajo: tus tres métricas, el enlace a tu motor y el enlace o la captura del recap ya enviado. Plazo: viernes a las 23:59 (hora de Madrid)."}, {"t": "note", "kind": "aviso", "text": "El recap tiene que estar enviado. Un documento que nadie ha abierto no es un sistema de visibilidad.", "title": "Enviado, no en borrador"}]$j$::jsonb
  where id = '482b2965-b352-49da-af5d-7ad9948f85b2' and md5(content_blocks::text) = '5b388c31be0b3d0296a51b90e7adea2c';
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'La lección 3 (es) ha cambiado: revisa antes de aplicar'; end if;

  update public.lessons set content_blocks_en = $j$[{"t": "p", "text": "Remote workers get promoted less because the people deciding lack information about their performance. This hour builds the answer: the Visibility Engine, a personal system that turns your work into verifiable evidence. You leave with the system running and three outcome metrics written down."}, {"t": "ul", "items": ["What the Visibility Engine is and its five components: RECAP", "A real weekly recap, opened on screen", "How to tell an outcome metric from an activity metric"]}, {"t": "checklist", "items": ["Your Value Provider Matrix row from hour 1", "A clear idea of the tool you use every day: a doc, a channel or a board", "Assignment 02 open on the campus (further down, under “Activities in this lesson”)"], "title": "Come prepared with"}, {"t": "h", "text": "Assignment 02 · Build your Visibility Engine", "level": 3}, {"t": "steps", "items": [{"text": "In the tool you already use, with the five RECAP fields set up.", "title": "Build the engine"}, {"text": "In the metrics template. Each one has to pass the four filters covered in class.", "title": "Write three outcome metrics"}, {"text": "To the channel the decision-maker actually reads, not to a private folder.", "title": "Send your first recap"}]}, {"t": "p", "text": "You submit it here on the campus, further down: your three metrics, the link to your engine and a link or screenshot of the recap once sent. Deadline: Friday at 23:59 (Madrid time)."}, {"t": "note", "kind": "aviso", "text": "The recap has to be sent. A document nobody has opened is not a visibility system.", "title": "Sent, not drafted"}]$j$::jsonb
  where id = '482b2965-b352-49da-af5d-7ad9948f85b2' and md5(content_blocks_en::text) = '99ba6ddb7042e9edaf18a52ac485b978';
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'La lección 3 (en) ha cambiado: revisa antes de aplicar'; end if;

  update public.lessons set content_blocks = $j$[{"t": "p", "text": "La hora 2 montó la versión escrita. Esta entrena la hablada: la que usas cuando te preguntan de golpe en qué andas y no hay tiempo de abrir un documento. Es la hora con menos teoría del módulo: la mayor parte del tiempo trabajas tú, escribiendo y hablando delante de tu grupo."}, {"t": "ul", "items": ["Qué es una actualización de impacto y su estructura en cuatro campos", "Escribir la tuya con tu semana real", "Decirla en voz alta y puntuar la de tus compañeros"]}, {"t": "checklist", "items": ["Tu recap o tus métricas de la hora 2", "Algo concreto que hayas entregado esta semana, con su número", "La Tarea 03 abierta en el campus (más abajo, en «Actividades de esta lección»)", "Cámara y micrófono que funcionen"], "title": "Trae preparado"}, {"t": "h", "text": "Tarea 03 · Graba tu actualización de impacto y úsala tres veces", "level": 3}, {"t": "steps", "items": [{"text": "Tu actualización con los cuatro campos, dicha en voz alta con el documento cerrado. Vale la primera toma decente.", "title": "Graba 60 segundos"}, {"text": "En momentos reales de esta semana: un stand-up, un mensaje, un uno a uno.", "title": "Úsala tres veces"}, {"text": "Una línea por momento: dónde, con quién y qué pasó.", "title": "Anota los tres momentos"}]}, {"t": "p", "text": "Entregas aquí, en el campus, más abajo, el enlace a tu vídeo y los tres momentos. Las dos partes son obligatorias. Plazo: viernes a las 23:59 (hora de Madrid)."}, {"t": "note", "kind": "aviso", "text": "El ejercicio consiste en no leer. Un vídeo leído se nota y no cumple el objetivo.", "title": "Sin leer"}]$j$::jsonb
  where id = '5f8b402d-3c41-416b-b9ee-02f6e84ed30c' and md5(content_blocks::text) = 'f9eed9bf74662241b34970f9e2465df8';
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'La lección 4 (es) ha cambiado: revisa antes de aplicar'; end if;

  update public.lessons set content_blocks_en = $j$[{"t": "p", "text": "Hour 2 built the written version. This one trains the spoken one: what you use when someone suddenly asks what you are working on and there is no time to open a document. It is the lightest hour of the module on theory. Most of the time you are the one working, writing and then speaking in front of your group."}, {"t": "ul", "items": ["What an impact update is and its four-field structure", "Writing yours from your real week", "Saying it out loud and scoring your peers"]}, {"t": "checklist", "items": ["Your recap or metrics from hour 2", "Something concrete you delivered this week, with its number", "Assignment 03 open on the campus (further down, under “Activities in this lesson”)", "A working camera and microphone"], "title": "Come prepared with"}, {"t": "h", "text": "Assignment 03 · Record your impact update and use it three times", "level": 3}, {"t": "steps", "items": [{"text": "Your update with its four fields, said out loud with the document closed. The first decent take counts.", "title": "Record 60 seconds"}, {"text": "In real moments this week: a stand-up, a message, a one-to-one.", "title": "Use it three times"}, {"text": "One line each: where, with whom and what happened.", "title": "Log the three moments"}]}, {"t": "p", "text": "You submit the link to your video and the three moments here on the campus, further down. Both parts are required. Deadline: Friday at 23:59 (Madrid time)."}, {"t": "note", "kind": "aviso", "text": "The whole point is not to read. A read-out video shows, and it misses the goal.", "title": "No reading"}]$j$::jsonb
  where id = '5f8b402d-3c41-416b-b9ee-02f6e84ed30c' and md5(content_blocks_en::text) = '23c1dbdc7bb1ff75f2f37744ada41a8d';
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'La lección 4 (en) ha cambiado: revisa antes de aplicar'; end if;

  update public.lessons set content_blocks = $j$[{"t": "p", "text": "La última hora es tuya. La mitad es un Q&A abierto sobre tus casos concretos, los que no caben en una diapositiva. Después se abre el puente al módulo 02, que trata de dónde te basas, y se explican los deberes para que nadie los empiece confundido."}, {"t": "ul", "items": ["Q&A abierto con tus casos", "El puente al módulo 02: dónde te basas", "Los deberes de la semana, explicados", "Cierre del módulo 01"]}, {"t": "checklist", "items": ["Lo que te preocupa del lunes y no se ha resuelto en clase", "Tus dudas sobre las tareas 01, 02 y 03"], "title": "Trae preparado"}, {"t": "note", "kind": "idea", "text": "Las preguntas concretas sirven más que las abstractas. En la sala casi siempre hay alguien que ya ha vivido lo que preguntas.", "title": "Pregunta por tu caso"}, {"t": "h", "text": "Los deberes de la semana", "level": 3}, {"t": "table", "head": ["Deberes", "Qué haces", "Se presenta en"], "rows": [["01 · Diagnóstico de Preparación Remota", "Puntúas los cinco ejes, escribes tu frase de valor verificable y nombras tu eje de foco", "Hora 1"], ["02 · Motor de Visibilidad", "Fijas la cadencia de tu recap, eliges tres métricas de resultado y envías tu primer recap", "Hora 2"], ["03 · Actualización de impacto", "Grabas 60 segundos sin leer y anotas los tres momentos reales en que la usaste", "Hora 3"], ["04 · Test de conocimientos", "Respondes el test de 20 preguntas de opción múltiple del módulo", "Hora 4"]], "caption": "Todo se hace y se entrega en el campus. Lo tienes junto en Mis tareas, con su fecha."}, {"t": "note", "kind": "aviso", "text": "Las cuatro actividades vencen el viernes a las 23:59 (hora de Madrid) y se hacen todas en el campus: las tienes juntas en Mis tareas. Las tareas 01 a 03 se devuelven con feedback en siete días. El test se corrige solo al enviarlo, aquí abajo.", "title": "Un único plazo"}]$j$::jsonb
  where id = '89ba59a8-dbef-4e08-bf34-b73fd2ce4a89' and md5(content_blocks::text) = '460a15fefc057f600faa88fe0c931351';
