  update public.lessons set content_blocks_en = $j$[{"t": "p", "text": "The last hour belongs to you. Half of it is an open Q&A on your specific cases, the ones that do not fit on a slide. Then comes the bridge to module 02, which is about where you base yourself, and a walk-through of the homework so nobody starts it confused."}, {"t": "ul", "items": ["Open Q&A on your cases", "The bridge to module 02: where you base yourself", "The week's homework, explained", "Closing module 01"]}, {"t": "checklist", "items": ["Whatever worries you about Monday that class has not solved", "Your questions about assignments 01, 02 and 03"], "title": "Come prepared with"}, {"t": "note", "kind": "idea", "text": "Specific questions help more than abstract ones. There is nearly always someone in the room who has already lived what you are asking about.", "title": "Ask about your own case"}, {"t": "h", "text": "This week's homework", "level": 3}, {"t": "table", "head": ["Homework", "What you do", "Introduced in"], "rows": [["01 · Remote Readiness Diagnostic", "Score the five axes, write your verifiable value statement and name your focus axis", "Hour 1"], ["02 · Visibility Engine", "Set your recap cadence, choose three outcome metrics and send your first recap", "Hour 2"], ["03 · Impact update", "Record 60 seconds without reading and log the three real moments you used it", "Hour 3"], ["04 · Knowledge check", "Answer the module's 20-question multiple-choice test", "Hour 4"]], "caption": "Everything is done and submitted on the campus. You'll find it all in My tasks, with its due date."}, {"t": "note", "kind": "aviso", "text": "All four are due on Friday at 23:59 (Madrid time) and are all done on the campus: you'll find them together in My tasks. Assignments 01 to 03 come back with feedback within seven days. The test is marked automatically when you submit it, below.", "title": "One deadline"}]$j$::jsonb
